"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["25752"],{22981(e,t,i){i.r(t),i.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>o,contentTitle:()=>h,toc:()=>d,assets:()=>p});var a=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","title":"Fetch certificate path","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-fetch-certs-path","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Fetch certificate path","sidebar_label":"Fetch certificate path","sidebar_class_name":"api-method api-method--post","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Participant details (v2 search)","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-participant-details"},"next":{"title":"Get linked registry master (internal)","permalink":"/docs/pr-10/docs/nhcx/v1/api/registry/endpoints/registry-get-linked-registry-mst"}}'),r=i(62540),n=i(43023),s=i(70862),c=JSON.parse('{"id":"registry_fetch_certs_path","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/fetch/certs/path","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Fetch certificate path","description":"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant\'s certificate path.\\n\\n### Business purpose\\n\\nThe registry stores a participant\'s encryption certificate as a URI or file path in the encryption_cert field, and this endpoint exposes that reference for a given participant. It exists alongside /fetch/certs, which the Integration Handbook names as the call to use when obtaining key material for encryption. Both serve the same underlying need, resolving a counterparty\'s public key before building a JWE, but the OpenAPI documents them identically and does not describe how their returned strings differ.\\n\\n### When to use\\n\\nUse it only if your HCX instance or onboarding contact tells you to; the chapter\'s guidance is to treat /fetch/certs as the one to use for encryption. Both endpoints are POST, both carry the Registry APIs tag, both take ParticipantCertRequest and both declare a string 200 response with 400, 404 and 500 ErrorResponse outcomes. It is a synchronous JSON registry call with no workflow or x-hcx-status codes.\\n\\n### Preconditions\\n\\n- Bearer token from /get/session in bearer_auth with the Bearer prefix; Accept and Content-Type: application/json.\\n- ParticipantCertRequest with participantid (required), the target\'s participant code in <code>@hcx form.\\n- The target participant has completed onboarding with an encryption certificate registered.\\n\\n### Postconditions\\n\\nHTTP 200 with a string body. The spec describes the operation (fetchCertsPath) with the same text as /fetch/certs, so the precise content of the string beyond being a certificate path is not documented. No registry state changes and no callback. Errors use the ErrorResponse envelope on 400, 404 and 500.\\n\\n### Common mistakes\\n\\n- Assuming this returns the same PEM as /fetch/certs and feeding a path string into a key-import routine.\\n- Choosing it over /fetch/certs for encryption without instance-specific guidance; the handbook names /fetch/certs.\\n- Passing participant_code instead of participantid.\\n- Omitting Accept or the Bearer prefix on the token.\\n\\n### Best practices\\n\\n- Prefer /fetch/certs for obtaining key material; use this endpoint only where the instance documents a use for the path form.\\n- If you do use it, log the returned string shape once so a change in behaviour is noticed.\\n- Apply the same 24-hour cache discipline keyed by participantid.\\n- Keep both calls behind one client function so the choice is a configuration switch.\\n\\n### Related scenario\\n\\nAn integrator building a registry inspection tool for a TPA wants to show, for each payer, where the registry references its certificate as well as the certificate itself. The tool obtains a Bearer token, calls /fetch/certs/path with participantid 1518@hcx and displays the returned path string, then calls /fetch/certs for the PEM used for actual encryption. The production claims engine itself only uses /fetch/certs, as the Integration Handbook prescribes, before each /v1/claim/submit.\\n\\n### Specification\\n\\nChapter [Finding participants and policies](/docs/nhcx/v1/getting-started/finding-participants-and-policies) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"participantid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"participantid":"1518@hcx"},"responses":[{"status":"200","description":"HTTP 200 with a string body.","example":{"_contentType":"string","_body":"<certificate path string as declared by the OpenAPI 200 response>"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","atom":null,"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/fetch/certs/path \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"participantid\\": \\"1518@hcx\\"\\n}\'"}');let o={title:"Fetch certificate path",sidebar_label:"Fetch certificate path",sidebar_class_name:"api-method api-method--post",description:"Companion to /fetch/certs: takes the same participantid body and returns a string described as the participant's certificate path.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},h,p={},d=[];function l(e){return(0,r.jsx)(s.A,{operation:c})}function u(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);